 rows=json.load(open(O/'dataset_manifest.json'));g={x['configuration']:{k:np.array(v) if k!='atoms' else v for k,v in x.items() if k!='configuration'} for x in json.load(open(O/'geometry_manifest.json'))};prov=json.load(open(O/'provenance.json'));z=np.load(O/'inputs.npz');delta=z['delta'];E=z['energy'];oldraw=Path(prov['old_raw']);newraw=Path(prov['new_dataset']);co=SPECIES.index('CO');h=SPECIES.index('H');pure=[i for i,r in enumerate(rows) if r['identity_labels']==['CO']];hmix=[i for i,r in enumerate(rows) if set(r['identity_labels'])=={'CO','H'}];desc=[];sourceparents=[];saved_parents={x['configuration']:x for x in json.load(open(O/'initial_parent_manifest.json'))} if (O/'initial_parent_manifest.json').exists() else {}
