 def item(rank,topic,hold,vary,decision,**extra):return dict(rank=rank,calculation=topic,hold_fixed=hold,vary=vary,decision_changing_result=decision,reservation='Reserve the entire new clean/CO-only/CO+H family and all its layer/site views for prospective checks; never split a family between training and evaluation',submit_jobs=False,**extra)
